        using var tree = new LayoutTree();

        var root = tree.CreateNode();
        tree.SetPositionType(root, PositionType.Absolute);
        tree.SetDimension(root, Dimension.Width, StyleLength.Points(300.0f));
        tree.SetDimension(root, Dimension.Height, StyleLength.Points(300.0f));
        tree.SetFlexDirection(root, FlexDirection.Row);
        tree.SetFlexWrap(root, Wrap.Wrap);
        tree.SetAlignContent(root, Align.Stretch);
        tree.SetAlignItems(root, Align.FlexEnd);

        var rootChild0 = tree.CreateNode();
        tree.SetDimension(rootChild0, Dimension.Height, StyleLength.Points(50.0f));
        tree.SetDimension(rootChild0, Dimension.Width, StyleLength.Points(150.0f));
        tree.SetAlignSelf(rootChild0, Align.FlexStart);
        tree.InsertChild(root, rootChild0, 0);

        var rootChild1 = tree.CreateNode();
        tree.SetDimension(rootChild1, Dimension.Height, StyleLength.Points(100.0f));
        tree.SetDimension(rootChild1, Dimension.Width, StyleLength.Points(120.0f));
        tree.InsertChild(root, rootChild1, 1);

        var rootChild2 = tree.CreateNode();
        tree.SetDimension(rootChild2, Dimension.Height, StyleLength.Points(50.0f));
        tree.SetDimension(rootChild2, Dimension.Width, StyleLength.Points(120.0f));
        tree.InsertChild(root, rootChild2, 2);
        tree.CalculateLayout(root, float.NaN, float.NaN, Direction.Ltr);

        Assert.Equal(0.0f, tree.GetLeft(root), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(root), Tolerance);
        Assert.Equal(300.0f, tree.GetWidth(root), Tolerance);
        Assert.Equal(300.0f, tree.GetHeight(root), Tolerance);

        Assert.Equal(0.0f, tree.GetLeft(rootChild0), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(rootChild0), Tolerance);
        Assert.Equal(150.0f, tree.GetWidth(rootChild0), Tolerance);
        Assert.Equal(50.0f, tree.GetHeight(rootChild0), Tolerance);

        Assert.Equal(150.0f, tree.GetLeft(rootChild1), Tolerance);
        Assert.Equal(75.0f, tree.GetTop(rootChild1), Tolerance);
        Assert.Equal(120.0f, tree.GetWidth(rootChild1), Tolerance);
        Assert.Equal(100.0f, tree.GetHeight(rootChild1), Tolerance);

        Assert.Equal(0.0f, tree.GetLeft(rootChild2), Tolerance);
